/bin/bash -lc "RUN=<HOME> .venv/bin/python - <<'PY'
import json,re,os
run='<HOME>'
keys=['kim2025key','derensy2026phase','makrovets2023y2o3','shevchenko2019thermodynamic','shevchenko2025experimental','kozhevnikova2024synthesis','mckenzie2021nucleation','zeng2024selective','wang2024optimal','dingwell1990relaxation','chen2024navigating','wang2022dataset','huo2022machine','gong2022calibrating']
text=open(run+'/library/references.bib').read()
entries={}
for m in re.finditer(r'@\\w+\\{(["'^,]+),'"\\n(.*?)(?=\\n\\n@|\\Z)',text,re.S):
 k=m.group(1); b=m.group(2)
 if k in keys:
  title=re.search(r'  title = \\{(.*?)\\},',b,re.S)
  entries[k]=re.sub(r'\\s+',' ',title.group(1)) if title else ''
rows=[]
for line in open(run+'/library/papers.jsonl'):
 try: rows.append(json.loads(line))
 except: pass
for k,t in entries.items():
 print('\\n###',k,t)
 hits=[r for r in rows if re.sub(r'["'^a-z0-9]'"','',r.get('title','').lower())==re.sub(r'["'^a-z0-9]'"','',t.lower())]
 if not hits:
  # fuzzy first words
  hits=[r for r in rows if t.lower().split()[0] in r.get('title','').lower()][:2]
 for r in hits[:2]:
  print('year',r.get('year'),'doi',r.get('doi'),'abstract', (r.get('abstract') or '')[:900].replace('\\n',' '))
PY"

